            frame(0, "p1", "00:00:00:00:00:01"),
            {"t": 1, "config": new},
        ]
        _, log_bytes = record(config, events)
        doc = json.loads(log_bytes.decode())
        # 顶层键序 schema,config,records,sha256
        self.assertEqual(list(doc), LOG_KEYS)
